parameters.jsCode:
const trigger = $('When Executed by Another Workflow').first().json;
const rawTaskId = trigger.task_id || new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-task';
const draftText = $input.first().json.text || $input.first().json.output || '';

// Count total words in the draft
const wordCount = draftText.trim().split(/\s+/).filter(Boolean).length;

// Detect if the LLM output contains a Python or JavaScript code block
const codeMatch = draftText.match(/```(python|javascript|js|py)\n([\s\S]*?)```/i);
const hasCode = Boolean(codeMatch);
const lang = codeMatch ? codeMatch[1].toLowerCase() : 'none';
const extractedCode = codeMatch ? codeMatch[2].trim() : '';
const ext = (lang === 'javascript' || lang === 'js') ? 'js' : 'py';

return [
  {
    json: {
      task_id: rawTaskId,
      has_code: hasCode,
      language: lang,
      code_filename: `solution.${ext}`,
      raw_code: extractedCode,
      draft_filename: `${rawTaskId}-v1.md`,
      word_count: wordCount,
      full_draft_markdown: draftText
    }
  }
];

const items = $input.all();

for (const item of items) {
  const codeStr = item.json.raw_code || "";

  // Split into lines and filter out empty whitespace lines
  const lines = codeStr.split('\n').filter(line => line.trim().length > 0);

  // Attach metrics to the output JSON
  item.json.code_line_count = lines.length;
  item.json.syntax_checked = true;
}

return items;
